from __future__ import annotations
import argparse, base64, html, json, mimetypes
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
DEFAULT_REFRESH=ROOT/'pet-art'/'refresh-20261023'
def uri(p):
    return 'data:%s;base64,%s'%(mimetypes.guess_type(p.name)[0] or 'application/octet-stream',base64.b64encode(p.read_bytes()).decode())
def maybe(p): return uri(p) if p.is_file() else None
def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--root',type=Path,default=DEFAULT_REFRESH,help='refresh task root')
    refresh=parser.parse_args().root
    refresh=refresh if refresh.is_absolute() else ROOT/refresh
    RUNTIME=refresh/'runtime-qa'; STAGING=refresh/'staging'; OUT=refresh/'preview.html'
    rows=[6,8,8,4,5,8,6,6,6,8,8]; labels=['待機','走路右','走路左','揮手','跳躍','拖曳','被摸','理毛','呼吸','追視A','追視B']; frames={}
    for r,n in enumerate(rows):
        frames['row-%d'%r]=[{'src':uri(p),'width':192,'height':208,'label':'%s %d/%d'%(labels[r],c+1,n),'baseline':([170,170,152,162,170][c] if r==4 and c<5 else 170)} for c in range(n) if (p:=RUNTIME/('atlas-%02d-%02d.png'%(r,c))).is_file()]
    for key,label in [('long-left','修長走路左'),('long-right','修長走路右')]:
        frames[key]=[{'src':uri(p),'width':256,'height':208,'label':'%s %d/8'%(label,i+1),'baseline':170} for i in range(8) if (p:=RUNTIME/('%s-%02d.png'%(key,i))).is_file()]
    for key,label in [('pellet','種子棒'),('broccoli','花椰菜')]:
        name='Pellet' if key=='pellet' else 'Broccoli'; frames[key]=[{'src':uri(p),'width':192,'height':208,'label':'%s %d/6'%(label,i+1),'baseline':170} for i in range(6) if (p:=RUNTIME/('feeding-%s-%02d.png'%(name,i))).is_file()]
    frames['bokchoy']=[{'src':uri(p),'width':192,'height':208,'label':'小白菜 %d/6'%(i+1),'baseline':170} for i in range(6) if (p:=RUNTIME/('feeding-BokChoy-%02d.png'%i)).is_file()]
    contacts=[{'name':p.name,'src':uri(p)} for p in sorted((STAGING/'qa').glob('*-contact.jpg'))]
    metrics=json.loads((STAGING/'qa'/'metrics.json').read_text(encoding='utf-8')) if (STAGING/'qa'/'metrics.json').is_file() else {}
    raw={'before':maybe(refresh/'before'/'Assets'/'spritesheet.png'),'after':maybe(STAGING/'Assets'/'spritesheet.png')}
    walk_qa=maybe(refresh/'qa'/'runtime-walking-before-after.png')
    action_qa=maybe(refresh/'qa'/'runtime-actions.png')
    css='''body{font-family:system-ui,"Microsoft JhengHei",sans-serif;margin:20px;background:#f5f5f5;color:#222}button,select{font:inherit;padding:6px;margin:3px;border:1px solid #999;border-radius:5px;background:#fff}.hint{font-size:13px;color:#555}.stage-area{width:384px;height:312px;position:relative}.stage{position:relative;width:256px;height:208px;overflow:hidden;background:#e7edf2;border:1px solid #778;transform-origin:0 0}.stage.dark{background:#20242b}.inner{position:absolute;width:256px;height:208px;left:0;top:0;transform-origin:0 0}.frame{position:absolute;top:0;height:208px;width:auto}.contact{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px}.contact img{max-width:100%;border:1px solid #aaa}.raw{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px}.raw>div{min-width:0;overflow:auto}.raw img{display:block;max-width:none;width:auto;height:auto;border:1px solid #888}.runtime-qa{max-width:100%;height:auto;border:1px solid #888}.metrics{white-space:pre-wrap;max-height:220px;overflow:auto;background:#fff;padding:8px;border:1px solid #aaa}'''
    template='''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>薯餅固定尺度預覽</title><style>__CSS__</style></head><body><h1>薯餅全動作固定尺度預覽</h1><p class="hint">固定舞台 256×208；一般/餵食影格 192×208 置中 x=32，修長影格 256×208 x=0。倍率只作用於共同外層。</p><h2>動作預覽</h2><div><label>動作 <select id="action"></select></label><button id="play">播放</button><button id="pause">暫停</button><button id="step">單格</button><button id="timeline">播放時間軸</button><label>模式 <select id="mode"><option value="current">一般</option><option value="long">修長</option></select></label><span>倍率</span><button data-scale=".75">75%</button><button data-scale="1">100%</button><button data-scale="1.5">150%</button><span>背景</span><button data-bg="light">亮</button><button data-bg="dark">暗</button></div><div id="status"></div><div class="stage-area"><div id="stage" class="stage"><div id="inner" class="inner"><img id="frame" class="frame" alt=""></div></div></div><input id="slider" type="range" min="0" value="0"><div id="flabel" class="hint"></div><h2>全動作 Contact Sheet</h2><div id="contacts" class="contact"></div><h2>素材原圖對照（未套用執行期校色與舊補償）</h2><p class="hint">before 備份與 staging 原始圖集以原始像素尺寸顯示，可水平捲動檢視；不代表舊版執行期畫面。</p><div class="raw"><div><b>before/Assets/spritesheet.png</b><div id="before"></div></div><div><b>staging/Assets/spritesheet.png</b><div id="after"></div></div></div>__WALKQA____ACTIONQA__<h2>校準資料</h2><div id="metrics" class="metrics"></div><script>const F=__FRAMES__;const C=__CONTACTS__;const R=__RAW__;const M=__METRICS__;const A=[['row-0','待機'],['row-1','走路右'],['row-2','走路左'],['row-3','揮手'],['row-4','跳躍'],['row-5','拖曳'],['row-6','被摸'],['row-7','理毛'],['row-8','呼吸'],['row-9','追視A'],['row-10','追視B'],['long-left','修長走路左'],['long-right','修長走路右'],['pellet','種子棒'],['broccoli','花椰菜'],['bokchoy','小白菜']];const $=id=>document.getElementById(id);const q=$('action'),mode=$('mode'),sl=$('slider'),im=$('frame'),stage=$('stage'),status=$('status'),fl=$('flabel');A.forEach(x=>{let o=document.createElement('option');o.value=x[0];o.textContent=x[1];q.appendChild(o)});let key='row-0',i=0,s=1,t=null,tt=null;function list(){let k=key;if(mode.value==='long'&&(k==='row-1'||k==='row-2'))k=k==='row-1'?'long-right':'long-left';return F[k]||[]}function draw(){let a=list();if(!a.length){status.textContent='沒有可用影格';return}i=Math.max(0,Math.min(i,a.length-1));let x=a[i];im.src=x.src;im.style.width=x.width+'px';im.style.height=x.height+'px';im.style.left=((256-x.width)/2)+'px';im.style.top='0px';$('stage').style.transform='scale('+s+')';sl.max=a.length-1;sl.value=i;fl.textContent=x.label+'｜基準線 y='+x.baseline+'｜'+x.width+'×'+x.height;status.textContent='動作 '+(A.find(x=>x[0]===key)||['',key])[1]+'｜第 '+(i+1)+' 格/'+a.length+'｜固定舞台 256×208｜共同倍率 '+Math.round(s*100)+'%'}function stop(){if(t){clearInterval(t);t=null}if(tt){clearTimeout(tt);tt=null}}function play(){stop();t=setInterval(()=>{i=(i+1)%Math.max(1,list().length);draw()},120)}function timeline(){stop();let food=['pellet','broccoli','bokchoy'].includes(key)&&F[key]&&F[key].length?key:(F.bokchoy&&F.bokchoy.length?'bokchoy':(F.broccoli&&F.broccoli.length?'broccoli':''));let z=[['row-0',[0,1,2,3,4,5]],['row-1',[0,1,2,3,4,5,6,7]]];if(food)z.push([food,[0,1,2,3,4,3,2,3,4,5]]);z.push(['row-4',[0,1,2,3,4]],['row-0',[0,1,2,3,4,5]]);let a=0,b=0;function go(){if(a>=z.length){tt=null;return}key=z[a][0];q.value=key;let seq=z[a][1];if(b>=seq.length){a++;b=0;go();return}i=seq[b++];draw();tt=setTimeout(go,120)}go()}q.onchange=()=>{stop();key=q.value;i=0;draw()};mode.onchange=()=>{stop();i=0;draw()};sl.oninput=()=>{stop();i=+sl.value;draw()};$('play').onclick=play;$('pause').onclick=stop;$('step').onclick=()=>{stop();i=(i+1)%Math.max(1,list().length);draw()};$('timeline').onclick=timeline;document.querySelectorAll('[data-scale]').forEach(b=>b.onclick=()=>{s=+b.dataset.scale;draw()});document.querySelectorAll('[data-bg]').forEach(b=>b.onclick=()=>stage.classList.toggle('dark',b.dataset.bg==='dark'));C.forEach(c=>{let d=document.createElement('div');d.innerHTML='<div class="hint">'+c.name+'</div><img src="'+c.src+'" alt="'+c.name+'">';$('contacts').appendChild(d)});if(R.before)$('before').innerHTML='<img src="'+R.before+'" alt="before raw atlas">';if(R.after)$('after').innerHTML='<img src="'+R.after+'" alt="staging raw atlas">';$('metrics').textContent=JSON.stringify(M,null,2);draw();</script></body></html>'''
    template=template.replace('__WALKQA__',('<h2>Runtime 走路前後對照</h2><p class="hint">固定 256×208 舞台；同執行期校色。before/after 僅在 runtime export 存在時顯示。</p><img class="runtime-qa" src="'+walk_qa+'" alt="runtime walking before after">' if walk_qa else ''))
    template=template.replace('__ACTIONQA__',('<h2>Runtime 全動作對照</h2><p class="hint">固定畫布與同執行期校色。</p><img class="runtime-qa" src="'+action_qa+'" alt="runtime actions">' if action_qa else ''))
    text=template.replace('__CSS__',css).replace('__FRAMES__',json.dumps(frames,ensure_ascii=False,separators=(',',':'))).replace('__CONTACTS__',json.dumps(contacts,ensure_ascii=False,separators=(',',':'))).replace('__RAW__',json.dumps(raw,ensure_ascii=False)).replace('__METRICS__',json.dumps(metrics,ensure_ascii=False,separators=(',',':')))
    OUT.write_text(text,encoding='utf-8');print(json.dumps({'output':str(OUT),'atlasFrames':sum(len(v) for k,v in frames.items() if k.startswith('row-')),'extraFrames':{k:len(v) for k,v in frames.items() if not k.startswith('row-')},'contacts':len(contacts),'bytes':OUT.stat().st_size},ensure_ascii=False))
if __name__=='__main__': main()
